fn expand_tilde(&self, arg: &str) -> String {
    if self.argument_policy.expand_tilde {
        nu_path::expand_tilde(arg).to_string_lossy().to_string()
    } else {
        arg.to_string()
    }
}

/// Performs glob expansion on `arg`. If the expansion found no matches or the pattern
/// is not a valid glob, then this returns the original string as the expansion result.
///
/// Note: This matches the default behavior of Bash, but is known to be
/// error-prone. We might want to change this behavior in the future.
fn expand_glob(&self, arg: &str, cwd: &Path, span: Span) -> Result<Vec<String>, ShellError> {
    if !self.argument_policy.expand_globs && !self.argument_policy.strip_cwd_prefix {
        return Ok(vec![arg.into()]);
    }
    if !self.argument_policy.expand_globs {
        return Ok(vec![arg.into()]);
    }

    let Ok(paths) = nu_glob::glob_with_parent(arg, self.argument_match_options(), cwd) else {
        return Ok(vec![arg.into()]);
    };

    let mut result = vec![];
    for path in paths {
        let path = path.map_err(|err| ShellError::IOErrorSpanned {
            msg: format!("{}: {:?}", err.path().display(), err.error()),
            span,
        })?;
        // Strip PWD from the resulting paths if possible.
        let path_stripped = path.strip_prefix(cwd).unwrap_or(&path);
        let path_string = path_stripped.to_string_lossy().to_string();
        result.push(path_string);
    }

    if result.is_empty() {
        result.push(arg.to_string());
    }

    Ok(result)
}

fn remove_quotes<'a>(&self, s: &'a str) -> &'a str {
    match self.quoted_string_kind(s) {
        QuotedStringKind::Double | QuotedStringKind::Single | QuotedStringKind::Backtick => {
            &s[1..s.len() - 1]
        }
        QuotedStringKind::Unquoted => s,
    }
}

fn remove_inner_quotes<'a>(&self, arg: &'a str) -> Cow<'a, str> {
    if !self.argument_policy.strip_inner_quotes {
        return Cow::Borrowed(arg);
    }
    // Check that `arg` is a long option.
    if !arg.starts_with("--") {
        return Cow::Borrowed(arg);
    }
    // Split `arg` on the first `=`.
    let Some((option, value)) = arg.split_once('=') else {
        return Cow::Borrowed(arg);
    };
    // Check that `option` doesn't contain quotes.
    if option.contains('"') || option.contains('\'') || option.contains('`') {
        return Cow::Borrowed(arg);
    }
    // Remove the outermost pair of quotes from `value`.
    let value = self.remove_quotes(value);
    Cow::Owned(format!("{option}={value}"))
}

pub(crate) fn convert_glob_exclude_patterns(
    &self,
    columns: &[Value],
) -> Result<Vec<String>, ShellError> {
    let _ = self.glob_policy.empty_pattern_is_error;
    let res = columns
        .iter()
        .map(|value| match &value {
            Value::String { val: s, .. } => Ok(s.clone()),
            _ => Err(ShellError::IncompatibleParametersSingle {
                msg: "Incorrect column format, Only string as column name".to_string(),
                span: value.span(),
            }),
        })
        .collect::<Result<Vec<String>, _>>()?;

    Ok(res)
}

pub(crate) fn parse_glob_exclude_flag(
    &self,
    paths_to_exclude: Option<Value>,
    span: Span,
) -> Result<(Vec<String>, Span), ShellError> {
    let _ = self.glob_policy.include_files;
    match paths_to_exclude {
        None => Ok((vec![], span)),
        Some(f) => {
            let pat_span = f.span();
            match f {
                Value::List { vals: pats, .. } => {
                    let p = self.convert_glob_exclude_patterns(pats.as_slice())?;
                    Ok((p, pat_span))
                }
                _ => Ok((vec![], span)),
            }
        }
    }
}

fn glob_walk_behavior(&self, depth: Option<usize>) -> WalkBehavior {
    WalkBehavior {
        depth: depth.unwrap_or(self.glob_policy.default_max_depth),
        ..Default::default()
    }
}

fn should_keep_glob_entry(
    &self,
    file_type: &std::fs::FileType,
    no_dirs: bool,
    no_files: bool,
    no_symlinks: bool,
) -> bool {
    let skip_dir = no_dirs || !self.glob_policy.include_directories;
    let skip_file = no_files || !self.glob_policy.include_files;
    let skip_symlink = no_symlinks || !self.glob_policy.include_symlinks;
    !(skip_dir && file_type.is_dir()
        || skip_file && file_type.is_file()
        || skip_symlink && file_type.is_symlink())
}

pub(crate) fn glob_entries_to_values<'a>(
    &self,
    ctrlc: Option<Arc<AtomicBool>>,
    glob_results: impl Iterator<Item = WalkEntry<'a>>,
    no_dirs: bool,
    no_files: bool,
    no_symlinks: bool,
    span: Span,
) -> Result<Vec<Value>, ShellError> {
    let mut result: Vec<Value> = Vec::new();
    for entry in glob_results {
        if nu_utils::ctrl_c::was_pressed(&ctrlc) {
            result.clear();
            return Err(ShellError::InterruptedByUser { span: None });
        }
        let file_type = entry.file_type();
        if self.should_keep_glob_entry(&file_type, no_dirs, no_files, no_symlinks) {
            result.push(Value::string(
                entry.into_path().to_string_lossy().to_string(),
                span,
            ));
        }
    }
    Ok(result)
}

fn partition_glob_prefix(
    &self,
    glob_pattern: &Spanned<String>,
) -> Result<(std::path::PathBuf, wax::Glob<'static>), ShellError> {
    let _ = self.glob_policy.empty_pattern_is_error;
    match WaxGlob::new(&glob_pattern.item) {
        Ok(p) => {
            let (prefix, glob) = p.partition();
            Ok((prefix, glob.into_owned()))
        }
        Err(e) => Err(ShellError::GenericError {
            error: "error with glob pattern".into(),
            msg: format!("{e}"),
            span: Some(glob_pattern.span),
            help: None,
            inner: vec![],
        }),
    }
}

fn canonicalize_glob_root(
    &self,
    prefix: std::path::PathBuf,
    cwd: String,
    glob_pattern: &Spanned<String>,
) -> Result<std::path::PathBuf, ShellError> {
    let _ = self.glob_policy.default_max_depth;
    match nu_path::canonicalize_with(prefix, cwd) {
        Ok(path) => Ok(path),
        Err(e) if e.to_string().contains("os error 2") => Ok(std::path::PathBuf::new()),
        Err(e) => Err(ShellError::GenericError {
            error: "error in canonicalize".into(),
            msg: format!("{e}"),
            span: Some(glob_pattern.span),
            help: None,
            inner: vec![],
        }),
    }
}

pub(crate) fn collect_filesystem_glob(
    &self,
    engine_state: &EngineState,
    stack: &mut Stack,
    call: &Call,
) -> Result<PipelineData, ShellError> {
    let ctrlc = engine_state.ctrlc.clone();
    let span = call.head;
    let glob_pattern: Spanned<String> = call.req(engine_state, stack, 0)?;
    let depth = call.get_flag(engine_state, stack, "depth")?;
    let no_dirs = call.has_flag(engine_state, stack, "no-dir")?;
    let no_files = call.has_flag(engine_state, stack, "no-file")?;
    let no_symlinks = call.has_flag(engine_state, stack, "no-symlink")?;
    let paths_to_exclude: Option<Value> = call.get_flag(engine_state, stack, "exclude")?;
    let (not_patterns, not_pattern_span) =
        self.parse_glob_exclude_flag(paths_to_exclude, span)?;

    if self.glob_policy.empty_pattern_is_error && glob_pattern.item.is_empty() {
        return Err(ShellError::GenericError {
            error: "glob pattern must not be empty".into(),
            msg: "glob pattern is empty".into(),
            span: Some(glob_pattern.span),
            help: Some("add characters to the glob pattern".into()),
            inner: vec![],
        });
    }

    let (prefix, glob) = self.partition_glob_prefix(&glob_pattern)?;
    let path = engine_state.cwd_as_string(Some(stack))?;
    let path = self.canonicalize_glob_root(prefix, path, &glob_pattern)?;
    let walk_behavior = self.glob_walk_behavior(depth);

    let result = if !not_patterns.is_empty() {
        let np: Vec<&str> = not_patterns.iter().map(|s| s as &str).collect();
        let glob_results = glob
            .walk_with_behavior(path, walk_behavior)
            .not(np)
            .map_err(|err| ShellError::GenericError {
                error: "error with glob's not pattern".into(),
                msg: format!("{err}"),
                span: Some(not_pattern_span),
                help: None,
                inner: vec![],
            })?
            .flatten();
        self.glob_entries_to_values(ctrlc, glob_results, no_dirs, no_files, no_symlinks, span)
    } else {
        let glob_results = glob.walk_with_behavior(path, walk_behavior).flatten();
        self.glob_entries_to_values(ctrlc, glob_results, no_dirs, no_files, no_symlinks, span)
    }?;

    Ok(result
        .into_iter()
        .into_pipeline_data(span, engine_state.ctrlc.clone()))
}

pub(crate) fn sanitize_ls_glob_pattern(
    &self,
    pattern_arg: Option<Spanned<NuGlob>>,
) -> Result<Option<Spanned<NuGlob>>, ShellError> {
    if let Some(path) = pattern_arg {
        if self.glob_policy.empty_pattern_is_error && path.item.as_ref().is_empty() {
            return Err(ShellError::FileNotFoundCustom {
                msg: "empty string('') directory or file does not exist".to_string(),
                span: path.span,
            });
        }
        if self.glob_policy.strip_ansi_from_pattern {
            match path.item {
                NuGlob::DoNotExpand(p) => Ok(Some(Spanned {
                    item: NuGlob::DoNotExpand(nu_utils::strip_ansi_string_unlikely(p)),
                    span: path.span,
                })),
                NuGlob::Expand(p) => Ok(Some(Spanned {
                    item: NuGlob::Expand(nu_utils::strip_ansi_string_unlikely(p)),
                    span: path.span,
                })),
            }
        } else {
            Ok(Some(path))
        }
    } else {
        Ok(pattern_arg)
    }
}

pub(crate) fn glob_value_from_evaluated(
    &self,
    expr: &Expression,
    result: Value,
) -> Result<Value, ShellError> {
    let span = result.span();
    match result {
        Value::String { val, .. }
            if self.glob_policy.quoted_variables_do_not_expand
                && matches!(
                    &expr.expr,
                    Expr::FullCellPath(_) | Expr::StringInterpolation(_)
                ) =>
        {
            Ok(Value::glob(val, expr.ty != Type::Glob, span))
        }
        other => Ok(other),
    }
}

fn configure_process_env(
    &self,
    command: &mut std::process::Command,
    engine_state: &EngineState,
    stack: &Stack,
) -> Result<(), ShellError> {
    let envs = env_to_strings(engine_state, stack)?;
    if self.process_policy.clear_environment {
        command.env_clear();
    }
    command.envs(envs);
    Ok(())
}

fn configure_process_stdio(
    &self,
    command: &mut std::process::Command,
    stack: &Stack,
) -> Result<Option<os_pipe::PipeReader>, ShellError> {
    let stdout = stack.stdout();
    let stderr = stack.stderr();
    if self.process_policy.merge_pipe_streams
        && matches!(stdout, OutDest::Pipe)
        && matches!(stderr, OutDest::Pipe)
    {
        let (reader, writer) = os_pipe::pipe()?;
        command.stdout(writer.try_clone()?);
        command.stderr(writer);
        Ok(Some(reader))
    } else {
        command.stdout(Stdio::try_from(stdout)?);
        command.stderr(Stdio::try_from(stderr)?);
        Ok(None)
    }
}

fn attach_pipeline_stdin(
    &self,
    command: &mut std::process::Command,
    input: PipelineData,
) -> Option<PipelineData> {
    match input {
        PipelineData::ByteStream(stream, metadata) => match stream.into_stdio() {
            Ok(stdin) => {
                command.stdin(stdin);
                None
            }
            Err(stream) => {
                command.stdin(Stdio::piped());
                Some(PipelineData::ByteStream(stream, metadata))
            }
        },
        PipelineData::Empty => {
            if self.process_policy.inherit_empty_stdin {
                command.stdin(Stdio::inherit());
            } else {
                command.stdin(Stdio::null());
            }
            None
        }
        value => {
            command.stdin(Stdio::piped());
            Some(value)
        }
    }
}

fn spawn_foreground_child(
    &self,
    command: std::process::Command,
    engine_state: &EngineState,
) -> Result<ForegroundChild, std::io::Error> {
    let _ = self.process_policy.use_foreground;
    #[cfg(windows)]
    {
        let _ = engine_state;
        ForegroundChild::spawn(command)
    }
    #[cfg(unix)]
    {
        ForegroundChild::spawn(
            command,
            engine_state.is_interactive,
            &engine_state.pipeline_externals_state,
        )
    }
}

fn write_pipeline_data(
    &self,
    mut engine_state: EngineState,
    mut stack: Stack,
    data: PipelineData,
    mut writer: impl Write,
) -> Result<(), ShellError> {
    if let PipelineData::ByteStream(stream, ..) = data {
        stream.write_to(writer)?;
    } else if let PipelineData::Value(Value::Binary { val, .. }, ..) = data {
        writer.write_all(&val)?;
    } else if self.process_policy.render_non_binary_with_table {
        stack.start_capture();
        if self.process_policy.disable_ansi_when_rendering {
            Arc::make_mut(&mut engine_state.config).use_ansi_coloring = false;
        }
        let output =
            crate::Table.run(&engine_state, &mut stack, &Call::new(Span::unknown()), data)?;
        for value in output {
            let bytes = value.coerce_into_binary()?;
            writer.write_all(&bytes)?;
        }
    }
    Ok(())
}

fn apply_external_args(
    &self,
    command: &mut std::process::Command,
    name: &Spanned<String>,
    args: Vec<Spanned<String>>,
) -> Result<(), ShellError> {
    let _ = self.process_policy.use_foreground;
    #[cfg(not(windows))]
    let _ = name;
    #[cfg(windows)]
    if self.is_cmd_internal_command(&name.item) {
        use std::os::windows::process::CommandExt;
        command.args(["/D", "/C", &name.item]);
        for arg in &args {
            command.raw_arg(self.escape_cmd_argument(arg)?.as_ref());
        }
        return Ok(());
    }
    command.args(args.into_iter().map(|s| s.item));
    Ok(())
}

pub(crate) fn exec_replace_current_process(
    &self,
    engine_state: &EngineState,
    stack: &mut Stack,
    call: &Call,
) -> Result<PipelineData, ShellError> {
    let cwd = engine_state.cwd(Some(stack))?;
    let name: Spanned<String> = call.req(engine_state, stack, 0)?;
    let paths = nu_engine::env::path_str(engine_state, stack, call.head)?;
