        return Err(self.command_not_found(&name.item, call.head, engine_state, stack));
    };

    let mut command = std::process::Command::new(executable);
    command.current_dir(&cwd);
    self.configure_process_env(&mut command, engine_state, stack)?;
    let args = self.eval_arguments_from_call(engine_state, stack, call)?;
    command.args(args.into_iter().map(|s| s.item));

    #[cfg(unix)]
    {
