#[derive(Clone, Copy, Debug)]
pub struct External {
    argument_policy: ArgumentExpansionPolicy,
    glob_policy: GlobResolutionPolicy,
    process_policy: ProcessLaunchPolicy,
    lookup_policy: CommandLookupPolicy,
    capture_policy: OutputCapturePolicy,
}

impl Default for External {
    fn default() -> Self {
        Self {
            argument_policy: ArgumentExpansionPolicy {
                expand_tilde: true,
                expand_globs: true,
                strip_inner_quotes: true,
                strip_cwd_prefix: true,
                case_sensitive_globs: true,
                require_literal_separator: false,
                require_literal_leading_dot: false,
                recursive_match_hidden_dir: true,
                allow_list_spread: true,
            },
            glob_policy: GlobResolutionPolicy {
                include_directories: true,
                include_files: true,
                include_symlinks: true,
                default_max_depth: usize::MAX,
                empty_pattern_is_error: true,
                strip_ansi_from_pattern: true,
                quoted_variables_do_not_expand: true,
            },
            process_policy: ProcessLaunchPolicy {
                clear_environment: true,
                inherit_empty_stdin: true,
                merge_pipe_streams: true,
                use_foreground: true,
                render_non_binary_with_table: true,
                disable_ansi_when_rendering: true,
            },
            lookup_policy: CommandLookupPolicy {
                search_current_dir_on_windows: true,
                run_command_not_found_hook: true,
                suggest_removed_commands: true,
                suggest_module_commands: true,
                fuzzy_match_commands: true,
                search_command_terms: true,
                include_nu_commands_in_which: true,
            },
