            },
        }
    }
}

impl Command for External {
    fn name(&self) -> &str {
        "run-external"
    }

    fn usage(&self) -> &str {
        "Runs external command."
    }

    fn signature(&self) -> nu_protocol::Signature {
        Signature::build(self.name())
            .input_output_types(vec![(Type::Any, Type::Any)])
            .required("command", SyntaxShape::String, "External command to run.")
            .rest("args", SyntaxShape::Any, "Arguments for external command.")
            .category(Category::System)
    }

    fn run(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let cwd = engine_state.cwd(Some(stack))?;

        // Find the absolute path to the executable. On Windows, set the
        // executable to "cmd.exe" if it's is a CMD internal command. If the
        // command is not found, display a helpful error message.
        let name: Spanned<String> = call.req(engine_state, stack, 0)?;
        let executable =
            self.resolve_external_executable(&name, engine_state, stack, call.head, &cwd)?;

        // Create the command.
        let mut command = std::process::Command::new(executable);

        // Configure PWD.
        command.current_dir(&cwd);

        // Configure environment variables.
        self.configure_process_env(&mut command, engine_state, stack)?;

        // Configure args.
        let args = self.eval_arguments_from_call(engine_state, stack, call)?;
        self.apply_external_args(&mut command, &name, args)?;

        // Configure stdout and stderr. If both are set to `OutDest::Pipe`,
        // we'll setup a pipe that merge two streams into one.
        let stderr = stack.stderr();
        let merged_stream = self.configure_process_stdio(&mut command, stack)?;

        // Configure stdin. We'll try connecting input to the child process
        // directly. If that's not possible, we'll setup a pipe and spawn a
        // thread to copy data into the child process.
        let data_to_copy_into_stdin = self.attach_pipeline_stdin(&mut command, input);

        // Spawn the child process. On Unix, also put the child process to
        // foreground if we're in an interactive session.
        let mut child = self.spawn_foreground_child(command, engine_state)?;

        // If we need to copy data into the child process, do it now.
        if let Some(data) = data_to_copy_into_stdin {
            let stdin = child.as_mut().stdin.take().expect("stdin is piped");
            let engine_state = engine_state.clone();
            let stack = stack.clone();
            thread::Builder::new()
                .name("external stdin worker".into())
                .spawn(move || {
                    let _ = write_pipeline_data(engine_state, stack, data, stdin);
                })
                .err_span(call.head)?;
        }

        // Wrap the output into a `PipelineData::ByteStream`.
        let child = ChildProcess::new(
            child,
            merged_stream,
            matches!(stderr, OutDest::Pipe),
            call.head,
        )?;
        Ok(PipelineData::ByteStream(
            ByteStream::child(child, call.head),
            None,
        ))
    }

    fn examples(&self) -> Vec<Example> {
        vec![
            Example {
                description: "Run an external command",
                example: r#"run-external "echo" "-n" "hello""#,
                result: None,
            },
            Example {
                description: "Redirect stdout from an external command into the pipeline",
                example: r#"run-external "echo" "-n" "hello" | split chars"#,
                result: None,
            },
            Example {
                description: "Redirect stderr from an external command into the pipeline",
                example: r#"run-external "nu" "-c" "print -e hello" e>| split chars"#,
                result: None,
            },
        ]
    }
}

impl External {
    fn argument_match_options(&self) -> nu_glob::MatchOptions {
        nu_glob::MatchOptions {
            case_sensitive: self.argument_policy.case_sensitive_globs,
            require_literal_separator: self.argument_policy.require_literal_separator,
            require_literal_leading_dot: self.argument_policy.require_literal_leading_dot,
            recursive_match_hidden_dir: self.argument_policy.recursive_match_hidden_dir,
        }
    }

    pub(crate) fn eval_arguments_from_call(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
    ) -> Result<Vec<Spanned<String>>, ShellError> {
        let cwd = engine_state.cwd(Some(stack))?;
        let mut args: Vec<Spanned<String>> = vec![];
        for (expr, spread) in call.rest_iter(1) {
            if self.is_bare_string(expr) {
                // If `expr` is a bare string, perform tilde-expansion,
                // glob-expansion, and inner-quotes-removal, in that order.
                for arg in self.eval_argument(engine_state, stack, expr, spread)? {
                    for expanded in self.apply_bare_string_expansions(&arg, &cwd, expr.span)? {
                        args.push(expanded.into_spanned(expr.span));
                    }
                }
            } else {
                for arg in self.eval_argument(engine_state, stack, expr, spread)? {
                    args.push(arg.into_spanned(expr.span));
                }
            }
        }
        Ok(args)
    }

    fn apply_bare_string_expansions(
        &self,
        arg: &str,
        cwd: &Path,
        span: Span,
    ) -> Result<Vec<String>, ShellError> {
        let tilde_expanded = if self.argument_policy.expand_tilde {
            self.expand_tilde(arg)
        } else {
            arg.to_string()
        };
        let glob_expanded = if self.argument_policy.expand_globs {
            self.expand_glob(&tilde_expanded, cwd, span)?
        } else {
            vec![tilde_expanded]
        };
        let mut output = Vec::with_capacity(glob_expanded.len());
        for glob_expanded in glob_expanded {
            if self.argument_policy.strip_inner_quotes {
                output.push(self.remove_inner_quotes(&glob_expanded).into_owned());
            } else {
                output.push(glob_expanded);
            }
        }
        Ok(output)
    }

    fn eval_argument(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        expr: &Expression,
        spread: bool,
    ) -> Result<Vec<String>, ShellError> {
        // Remove quotes from string literals.
        let mut expr = expr.clone();
        if let Expr::String(s) = &expr.expr {
            expr.expr = Expr::String(self.remove_quotes(s).into());
        }

        let eval = get_eval_expression(engine_state);
        match eval(engine_state, stack, &expr)? {
            Value::List { vals, .. } => {
                self.coerce_list_argument(engine_state, expr.span, vals, spread)
            }
            value => self.coerce_scalar_argument(expr.span, value, spread),
        }
    }

    fn coerce_list_argument(
        &self,
        engine_state: &EngineState,
        span: Span,
        vals: Vec<Value>,
        spread: bool,
    ) -> Result<Vec<String>, ShellError> {
        if spread && self.argument_policy.allow_list_spread {
            vals.into_iter()
                .map(|val| val.coerce_into_string())
                .collect()
        } else {
            Err(ShellError::CannotPassListToExternal {
                arg: String::from_utf8_lossy(engine_state.get_span_contents(span)).into(),
                span,
            })
        }
    }

    fn coerce_scalar_argument(
        &self,
        span: Span,
        value: Value,
        spread: bool,
    ) -> Result<Vec<String>, ShellError> {
        if spread && self.argument_policy.allow_list_spread {
            Err(ShellError::CannotSpreadAsList { span })
        } else if spread {
            Err(ShellError::CannotSpreadAsList { span })
        } else {
            Ok(vec![value.coerce_into_string()?])
        }
    }

